       [("Break-even", "be = rs/od"), ("On-demand cost", "co = od*hm*ut"), ("Reserved cost", "cr = rs*hm"), ("Effective spot price", "se = sp*(1 + pq*rw)"), ("Saving", "sv = 1 - cr/co")], ["be", "co", "cr", "se", "sv"], {"od": "0.40 USD/h", "rs": "0.25 USD/h", "ut": "80 %", "sp": "0.12 USD/h", "pq": "15 %", "rw": "50 %"},
